Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 210;
const int INF = 0x3f3f3f3f;

int cap[MAXN*MAXN*2][MAXN*MAXN*2], flow[MAXN*MAXN*2][MAXN*MAXN*2];
int h[MAXN*MAXN*2], cnt[MAXN*MAXN*2];
int N, T, S, Tgt;

int get_id(int i, int j) {
    return (i-1)*N + j;
}

bool in_range(int x, int y) {
    return x>=1 && x<=N && y>=1 && y<=N;
}

void add_cap(int u, int v, int c) {
    cap[u][v] += c;
}

int augment(int u, int limit) {
    if (u == Tgt) return limit;
    int pushed = limit, delta, min_dist = N*N*2+2;
    for (int v = 0; v < N*N*2+2; ++v) {
        if (cap[u][v] - flow[u][v] > 0) {
            if (h[u] == h[v] + 1) {
                delta = augment(v, min(pushed, cap[u][v] - flow[u][v]));
                flow[u][v] += delta;
                flow[v][u] -= delta;
                pushed -= delta;
                if (h[S] == N*N*2+2 || pushed == 0) return limit - pushed;
            }
            min_dist = min(min_dist, h[v] + 1);
        }
    }
    if (pushed == limit) {
        cnt[h[u]]--;
        cnt[min_dist]++;
        if (cnt[h[u]] == 0) h[S] = N*N*2+2;
        h[u] = min_dist;
    }
    return limit - pushed;
}

int dinic() {
    if (S == Tgt) return INF;
    memset(flow, 0, sizeof(flow));
    memset(h, 0, sizeof(h));
    memset(cnt, 0, sizeof(cnt));
    int result = 0;
    while (h[S] < N*N*2+2) {
        result += augment(S, INF);
    }
    return result;
}

struct State {
    int x, y, steps;
};

int dist_from_start[MAXN][MAXN];
bool visited_bfs[MAXN][MAXN];
char board1[MAXN][MAXN], board2[MAXN][MAXN];
int start_x, start_y;
const int dr[4] = {0,0,-1,1};
const int dc[4] = {-1,1,0,0};

void bfs_start() {
    queue<State> q;
    q.push({start_x, start_y, 0});
    memset(dist_from_start, 0x7f, sizeof(dist_from_start));
    memset(visited_bfs, 0, sizeof(visited_bfs));
    visited_bfs[start_x][start_y] = true;
    while (!q.empty()) {
        State cur = q.front(); q.pop();
        dist_from_start[cur.x][cur.y] = cur.steps;
        if (cur.steps > T) break;
        for (int k=0; k<4; ++k) {
            int nx = cur.x + dr[k], ny = cur.y + dc[k];
            if (in_range(nx,ny) && board1[nx][ny] != 'Y' && !visited_bfs[nx][ny]) {
                State nxt = {nx, ny, cur.steps+1};
                visited_bfs[nx][ny] = true;
                q.push(nxt);
            }
        }
    }
}

void bfs_from_cell(int i, int j) {
    queue<State> q;
    q.push({i, j, 0});
    memset(visited_bfs, 0, sizeof(visited_bfs));
    visited_bfs[i][j] = true;
    while (!q.empty()) {
        State cur = q.front(); q.pop();
        if (cur.steps > T) break;
        if (dist_from_start[cur.x][cur.y] < cur.steps) continue;
        if (dist_from_start[cur.x][cur.y] == cur.steps && (board2[cur.x][cur.y] < '1' || board2[cur.x][cur.y] > '9')) continue;
        if (board2[cur.x][cur.y] >= '1' && board2[cur.x][cur.y] <= '9') {
            if (cur.x != i || cur.y != j) {
                add_cap(get_id(i,j), get_id(cur.x,cur.y) + N*N, INF);
            }
            if (dist_from_start[cur.x][cur.y] == cur.steps) continue;
        }
        for (int k=0; k<4; ++k) {
            int nx = cur.x + dr[k], ny = cur.y + dc[k];
            if (in_range(nx,ny) && board1[nx][ny] != 'Y' && !visited_bfs[nx][ny]) {
                State nxt = {nx, ny, cur.steps+1};
                visited_bfs[nx][ny] = true;
                q.push(nxt);
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    cin >> N >> T;
    for (int i=1; i<=N; ++i) cin >> (board1[i]+1);
    for (int i=1; i<=N; ++i) cin >> (board2[i]+1);

    S = 0; Tgt = 2*N*N+1;
    for (int i=1; i<=N; ++i) {
        for (int j=1; j<=N; ++j) {
            if (board1[i][j]>='1' && board1[i][j]<='9') {
                add_cap(S, get_id(i,j), board1[i][j]-'0');
            }
            if (board1[i][j]=='Z') {
                start_x = i; start_y = j;
            }
        }
    }
    for (int i=1; i<=N; ++i) {
        for (int j=1; j<=N; ++j) {
            add_cap(get_id(i,j), get_id(i,j)+N*N, INF);
            if (board2[i][j]>='1' && board2[i][j]<='9') {
                add_cap(get_id(i,j)+N*N, Tgt, board2[i][j]-'0');
            }
        }
    }
    bfs_start();
    for (int i=1; i<=N; ++i) {
        for (int j=1; j<=N; ++j) {
            if (board1[i][j]>='1' && board1[i][j]<='9') {
                bfs_from_cell(i,j);
            }
        }
    }
    cout << dinic() << '\n';
    return 0;
}
